'use strict';
(() => {
  const {stages, checks} = MC;
  const KEY='mathorcup-control-v1';
  const $=s=>document.querySelector(s);
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',check:'M9 11l3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',copy:'M9 9h12v12H9zM15 5V3H3v12h2',arrow:'M5 12h14M14 7l5 5-5 5',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',flag:'M4 22V3M4 3c5-4 11 4 16 0v10c-5 4-11-4-16 0',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',activity:'M2 12h5l3-9 4 18 3-9h5'};
  const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
  let state, loadProblem='', storageOkay=true, view='workbench', stageFilter='all', statusFilter='all', quick='all', query='', selected=null, dirty=false, pendingConfirm=null, scanTime=null;
  try { const raw=localStorage.getItem(KEY); state=raw?MC.validate(JSON.parse(raw)):MC.initial(); if(raw){const old=JSON.parse(raw); state.updatedAt=old.updatedAt;state.log=Array.isArray(old.log)?old.log.filter(l=>typeof l.text==='string'&&typeof l.at==='string').slice(0,40):[];state.duplicateReviews=old.duplicateReviews&&typeof old.duplicateReviews==='object'?old.duplicateReviews:{};} }
  catch(e){state=MC.initial();loadProblem='无法读取本地备份，当前显示空白模板。请通过「数据与备份」先导出原始存储，再决定是否导入备份。';}
  const labels={todo:'待开始',doing:'进行中',review:'待复核',done:'已完成',blocked:'已阻塞'};
  const stageName=id=>stages.find(s=>s.id===id)?.name||'';
  function taskStatus(t){if(MC.ready(state,t))return {text:'可开始',cls:'ready'};if(t.status==='todo'&&MC.missing(state,t).length)return {text:'待前置',cls:'todo'};return {text:labels[t.status],cls:t.status};}
  const statusBadge=t=>{const s=taskStatus(t);return `<span class="status ${s.cls}">${s.text}</span>`;};
  const stageBadge=t=>{const s=stages.find(s=>s.id===t.stage);return `<span class="stage-badge" style="--stage-color:${s.color}"><i></i>${s.name}</span>`;};
  const done=()=>state.tasks.filter(t=>t.status==='done').length;
  const readyCount=()=>state.tasks.filter(t=>MC.ready(state,t)).length;
  const issueKey=i=>[i.a,i.b,i.type,i.detail].join('|');
  const reviewed=i=>state.duplicateReviews?.[issueKey(i)]===true;
  const allIssues=()=>MC.duplicates(state);
  const unresolved=()=>allIssues().filter(i=>!reviewed(i));
  const dateLabel=d=>{try{return new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}catch{return '—';}};
  function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
  function save(){
    try {localStorage.setItem(KEY,JSON.stringify(state));storageOkay=true;loadProblem='';}catch(e){storageOkay=false;toast('浏览器保存失败，请立即导出备份');}
    $('#save-indicator').textContent=storageOkay?'已保存至此浏览器':'保存失败，请导出';
    return storageOkay;
  }
  function changeView(v){view=v;render();window.scrollTo({top:0,behavior:'smooth'});}
  function renderNav(){
    const items=[['workbench','grid','项目总表'],['handoffs','link','交付物交接'],['checklist','check','最终自检'],['duplicates','copy','重复工作检查']];
    $('#main-nav').innerHTML=items.map(([id,ic,title])=>`<button class="nav-button ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='duplicates'&&unresolved().length?`<span class="nav-count">${unresolved().length}</span>`:''}</button>`).join('');
    $('#stage-nav').innerHTML=stages.map(s=>{const ts=state.tasks.filter(t=>t.stage===s.id);return `<button class="stage-nav-item" data-stage="${s.id}"><i class="stage-dot" style="--stage-color:${s.color}"></i><span>${s.name}阶段</span><span>${ts.filter(t=>t.status==='done').length} / ${ts.length}</span></button>`;}).join('');
  }
  function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="label-small">MATHORCUP / PROJECT WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
  const addButton=()=>`<button class="btn primary" data-action="add">${icon('plus')}新增任务</button>`;
  function workflow(){return `<div class="workflow" aria-label="阶段顺序">${stages.map((s,i)=>{const ts=state.tasks.filter(t=>t.stage===s.id),d=ts.filter(t=>t.status==='done').length;return `<button class="workflow-step ${stageFilter===s.id?'selected':''}" data-stage="${s.id}" aria-pressed="${stageFilter===s.id}"><span class="step-no">${d===ts.length?'✓':'0'+(i+1)}</span><span class="step-info"><b>${s.name}</b><small>${d} / ${ts.length} 已完成</small></span></button>`;}).join('')}</div>`;}
  function workbench(){
    const total=state.tasks.length,d=done(),pct=Math.round(d/total*100),current=MC.next(state),blocked=state.tasks.filter(t=>t.status==='blocked').length,active=state.tasks.filter(t=>['doing','review'].includes(t.status)).length;
    return heading('竞赛项目总控台','把复杂的竞赛，拆成下一步可以执行的任务。',`<button class="btn secondary-action" data-action="export">${icon('download')}导出备份</button>${addButton()}`)+
      `<div class="summary-strip"><div class="stat"><div><div class="stat-label">全部任务</div><div class="stat-number">${total}<small>项</small></div></div><span class="stat-icon">${icon('grid')}</span></div><div class="stat"><div><div class="stat-label">正在推进</div><div class="stat-number">${active.toString().padStart(2,'0')}<small>项</small></div></div><span class="stat-icon">${icon('clock')}</span></div><div class="stat"><div><div class="stat-label">已完成</div><div class="stat-number">${d.toString().padStart(2,'0')}<small>/ ${total}</small></div></div><span class="stat-icon">${icon('check')}</span></div><div class="stat"><div><div class="stat-label">需要关注</div><div class="stat-number">${(blocked+unresolved().length).toString().padStart(2,'0')}<small>项</small></div></div><span class="stat-icon">${icon('flag')}</span></div></div>`+
      `<div class="overview-grid"><section class="focus-card"><div class="focus-top">${icon('spark')}AI 总负责 · 流程调度<span>根据依赖生成建议</span></div><h2>${current?`<span class="task-code">${escape(current.id)}</span>${escape(current.title)}`:'所有任务已完成'}</h2><p>${current?escape(current.goal):'交付链已闭合。导出项目记录，并妥善保存最终提交包。'}</p><div class="focus-bottom">${current?`<button class="btn primary" data-open="${current.id}">${current.status==='todo'?'查看当前任务':'继续推进任务'}${icon('arrow')}</button>`:`<button class="btn primary" data-action="export">导出完整记录${icon('download')}</button>`}<span class="next-note">${current?'可复制执行指令，交给对应 AI 执行。':'每个结论，都有可追溯的交付。'}</span></div></section><section class="project-pulse"><div class="section-mini"><h3>整体进度</h3><small>PROJECT PULSE</small></div><div class="progress-summary"><strong>${pct}%</strong><span>任务完成率</span></div><div class="progress-bar" role="progressbar" aria-label="任务完成率" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><div class="pulse-line"><span>当前可开始</span><b>${readyCount()} 项任务</b></div><div class="pulse-line"><span>自检通过</span><b>${checks.filter(c=>state.checks[c[0]]).length} / ${checks.length} 项</b></div><div class="pulse-line"><span>项目模式</span><b>个人 · 浏览器内保存</b></div></section></div>`+workflow()+
      `<section class="panel"><div class="panel-heading"><h2>项目总表 <span>PROJECT TASKS</span></h2><button class="tiny-link" data-action="activity">查看操作记录 ↗</button></div><div class="filter-bar"><button class="filter-chip ${quick==='all'?'active':''}" data-quick="all">全部任务</button><button class="filter-chip ${quick==='ready'?'active':''}" data-quick="ready">可开始 · ${readyCount()}</button><select class="filter-select" id="stage-filter" aria-label="按阶段筛选"><option value="all">全部阶段</option>${stages.map(s=>`<option value="${s.id}" ${stageFilter===s.id?'selected':''}>${s.name}阶段</option>`).join('')}</select><select class="filter-select" id="status-filter" aria-label="按状态筛选"><option value="all">全部状态</option>${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${statusFilter===v?'selected':''}>${l}</option>`).join('')}</select><label class="search-box">${icon('search')}<input id="task-search" aria-label="搜索任务" placeholder="搜索任务、编号或交付物…" value="${escape(query)}"></label></div><div id="tasks-region"></div></section>`;
  }
  function renderTasks(){if(!$('#tasks-region'))return;const ordered=state.tasks.slice().sort((a,b)=>stages.findIndex(s=>s.id===a.stage)-stages.findIndex(s=>s.id===b.stage)||a.order-b.order);const filtered=ordered.filter(t=>(stageFilter==='all'||t.stage===stageFilter)&&(statusFilter==='all'||t.status===statusFilter)&&(quick!=='ready'||MC.ready(state,t))&&[t.id,t.title,t.expected,t.artifacts,t.role].join(' ').toLowerCase().includes(query.toLowerCase()));
    $('#tasks-region').innerHTML=filtered.length?`<div class="table-wrap"><table class="task-table"><thead><tr><th>顺序</th><th>任务名称</th><th>阶段</th><th>状态</th><th>前置任务</th><th>实际交付</th><th>操作</th></tr></thead><tbody>${filtered.map(t=>`<tr><td class="order-cell">${String(ordered.indexOf(t)+1).padStart(2,'0')}</td><td><div class="task-name"><span class="task-symbol">${icon(t.status==='done'?'check':'file')}</span><button class="task-link" data-open="${t.id}"><strong>${escape(t.title)}</strong><small>${escape(t.id)} · ${escape(t.role)}</small></button></div></td><td>${stageBadge(t)}</td><td>${statusBadge(t)}</td><td>${t.deps.length?`<span title="${escape(t.deps.map(id=>MC.get(state,id).title).join('、'))}" style="font-size:9px">${t.deps.length>2?t.deps.length+' 项前置':t.deps.join(' / ')}</span>`:'<span style="font-size:9px">起点任务</span>'}</td><td class="delivery-state" title="${escape(t.artifacts||'尚未登记实际文件或链接')}">${t.artifacts?'✓ 已登记':'— 待交付'}</td><td><button class="table-action" data-open="${t.id}" aria-label="查看 ${escape(t.title)}">查看${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>显示 ${filtered.length} / ${state.tasks.length} 项任务</span><span>按阶段排列 · 执行顺序以实际前置依赖为准</span></div>`:`<div class="empty-state">${icon('search')}<b>没有符合条件的任务</b>换一个关键词，或清除筛选条件。<br><button class="tiny-link" style="margin-top:10px" data-action="clear-filters">清除全部筛选</button></div>`;
  }
  function handoffs(){return heading('交付物交接','从上一步的真实交付，走向下一步的明确输入。',`<button class="btn" data-action="export">${icon('download')}导出记录</button>`)+`<div class="info-card view-intro"><strong>一条可以追溯的工作链。</strong> 每个任务单独登记产出文件和交接说明，下游任务可直接查看并复制到执行指令中。文件路径仅作登记，请在实际执行环境中提供对应文件。</div><div class="handoff-list">${state.tasks.map(t=>{const downstream=state.tasks.filter(n=>n.deps.includes(t.id));return `<section class="panel handoff-card"><div class="handoff-title"><span class="task-code">${escape(t.id)} / ${stageName(t.stage)}</span><h3><button class="task-link" data-open="${t.id}">${escape(t.title)}</button></h3>${statusBadge(t)}</div><div class="handoff-column"><label>本步交付 →</label><p>${escape(t.artifacts||'尚未登记实际交付物')}</p><small>${escape(t.note||'完成后填写关键结论与下一步注意事项')}</small></div><span class="handoff-arrow">${icon('arrow')}</span><div class="handoff-column"><label>下一步输入</label>${downstream.length?downstream.map(n=>`<button class="tiny-link" data-open="${n.id}">${escape(n.id)} ${escape(n.title)} ↗</button><br>`).join(''):'<p>最终提交归档</p>'}<small>${t.status==='done'?'已满足此项前置依赖':'需完成本步后，才可作为已确认输入'}</small></div></section>`;}).join('')}</div>`;}
  function checklist(){const n=checks.filter(c=>state.checks[c[0]]).length,total=state.tasks.length,d=done(),q=state.tasks.find(t=>t.id==='Q03');return heading('最终自检','交付之前，把容易遗漏的地方再核对一遍。')+`<div class="check-grid"><section class="panel"><div class="panel-heading"><h2>提交前检查清单 <span>${n} / ${checks.length} 已核对</span></h2>${icon('shield')}</div>${checks.map(c=>`<label class="check-item ${state.checks[c[0]]?'checked':''}"><input type="checkbox" data-check="${c[0]}" ${state.checks[c[0]]?'checked':''}><span><b>${c[1]}</b><small>${c[2]}</small></span></label>`).join('')}</section><aside class="panel check-aside"><h3>提交准备度</h3><div class="progress-summary"><strong>${Math.round(n/checks.length*100)}%</strong><span>自检已确认</span></div><div class="progress-bar"><span style="width:${n/checks.length*100}%"></span></div><div class="gate-row"><span>任务完成</span><b>${d} / ${total}</b></div><div class="gate-row"><span>自检通过</span><b>${n} / ${checks.length}</b></div><div class="gate-row"><span>阻塞任务</span><b>${state.tasks.filter(t=>t.status==='blocked').length} 项</b></div><div class="gate-row"><span>待核对重复项</span><b>${unresolved().length} 项</b></div>${q?`<button class="btn primary" data-open="Q03">查看最终提交任务 ${icon('arrow')}</button>`:''}<p>勾选表示你已人工确认。最终任务只有在前置完成、交付完整、全部自检勾选后才能完成。重复检查是线索提示，不代替人工判断。</p></aside></div>`;}
  function duplicates(){const issues=allIssues(),count=unresolved().length;return heading('重复工作检查','先复用已有成果，再安排新的工作。')+`<section class="panel scan-header"><span class="scan-icon">${icon('copy')}</span><div><h2>${count?'发现 '+count+' 项待核对线索':'当前没有未核对的重复线索'}</h2><p>${scanTime?'最近检查 '+dateLabel(scanTime):'已根据当前任务与交付物自动检查'} · 共 ${state.tasks.length} 项任务</p></div><button class="btn primary" data-action="scan">${icon('search')}重新检查</button></section><section class="panel">${issues.length?issues.map((i,idx)=>`<article class="issue"><div class="issue-top"><b>${escape(i.type)}</b><span class="status ${reviewed(i)?'done':'review'}">${reviewed(i)?'已核对':'待核对'}</span></div><p>${escape(i.detail)}</p><div class="issue-actions"><button class="btn" data-open="${i.a}">查看 ${escape(i.a)}</button><button class="btn" data-open="${i.b}">查看 ${escape(i.b)}</button><button class="tiny-link" data-review-issue="${idx}">${reviewed(i)?'撤销核对':'已人工核对，可保留'}</button></div></article>`).join(''):`<div class="empty-state">${icon('shield')}<b>任务边界清晰</b>新增任务或登记交付物后，这里会自动更新。</div>`}</section><div class="rules-grid"><div class="rule"><b>01 / 相似任务</b><p>用任务名称的文字相似度发现重复安排的线索，不代表任务确实重复。</p></div><div class="rule"><b>02 / 同名交付</b><p>比较实际文件路径和预期交付物，提示可能的覆盖或重复产出。</p></div><div class="rule"><b>03 / 人工核对</b><p>确认任务范围与文件版本后再保留。本工具不检测论文查重率或 AI 生成率。</p></div></div>`;}
  function render(){renderNav();$('#app').innerHTML=(loadProblem?`<div class="notice">${escape(loadProblem)} <button class="tiny-link" data-action="data">数据与备份 ↗</button></div>`:'')+({workbench,handoffs,checklist,duplicates}[view]||workbench)();if(view==='workbench')renderTasks();$('#save-indicator').textContent=storageOkay?(state.updatedAt?'已保存至此浏览器':'进度保存在此浏览器'):'保存失败，请导出';}
  function mayClose(){return !dirty||window.confirm('本次修改尚未保存，确定放弃修改？');}
  function detail(id){if(selected&&dirty&&!mayClose())return;selected=id;dirty=false;const t=MC.get(state,id),deps=t.deps.map(id=>MC.get(state,id)),next=state.tasks.filter(n=>n.deps.includes(id)),locked=MC.missing(state,t).length>0;
    $('#detail-dialog').innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">${escape(t.id)} / ${stageName(t.stage)}阶段</div><h2 id="detail-title">${escape(t.title)}</h2>${statusBadge(t)}</div><button class="close-button" data-close="detail" aria-label="关闭任务详情">×</button></div><form id="task-form"><div class="dialog-body"><div id="detail-error" role="alert"></div>${locked?`<div class="notice">等待前置任务完成：${MC.missing(state,t).join('、')}。可先准备材料和登记说明。</div>`:''}<section><div class="two-fields"><label class="field"><span>任务名称</span><input name="title" value="${escape(t.title)}" maxlength="100" required></label><label class="field"><span>执行角色</span><select name="role">${[...new Set([...stages.map(s=>s.role),t.role])].map(r=>`<option ${r===t.role?'selected':''}>${escape(r)}</option>`).join('')}</select></label></div><label class="field"><span>本步目标</span><textarea name="goal" maxlength="30000" ${t.status==='done'?'readonly':''}>${escape(t.goal)}</textarea></label></section><section><h3>上一步交付 · 本步输入</h3>${deps.length?deps.map(p=>`<div class="dependency"><div class="dependency-head"><button class="tiny-link" type="button" data-open="${p.id}">${escape(p.id)} ${escape(p.title)} ↗</button>${statusBadge(p)}</div><p><strong>实际交付：</strong>${escape(p.artifacts||'尚未登记')}<br><strong>交接说明：</strong>${escape(p.note||'尚未登记')}</p></div>`).join(''):`<div class="dependency"><p style="margin:0">起点任务：先准备实际赛题与附件。</p></div>`}<p style="font-size:10px;color:#96a49a">输入要求：${escape(t.input)}</p></section><section><h3>本步交付</h3><div class="expected-box">预期：${escape(t.expected)}</div><label class="field" style="margin-top:15px"><span>实际交付物 <small style="display:inline">· 完成必填</small></span><textarea name="artifacts" maxlength="30000" placeholder="填写实际文件路径或链接，每行一项" ${t.status==='done'?'readonly':''}>${escape(t.artifacts)}</textarea><small>仅登记路径或链接，不会自动上传文件。</small></label><label class="field"><span>交接说明 <small style="display:inline">· 完成必填</small></span><textarea name="note" maxlength="30000" placeholder="关键结论、数据口径、验证结果与下一步注意事项…" ${t.status==='done'?'readonly':''}>${escape(t.note)}</textarea></label><button type="button" class="btn soft" data-action="prompt">${icon('copy')}生成 AI 执行指令</button></section><section><h3>下一步将使用本次交付</h3><div class="downstream">${next.length?next.map(n=>`<button type="button" data-open="${n.id}">${escape(n.id)} ${escape(n.title)} ↗</button>`).join(''):'<span style="font-size:11px;color:#9eada3">最终归档 · 导出项目记录</span>'}</div></section></div><div class="dialog-actions"><button class="btn" type="submit">保存交接记录</button>${t.status==='done'?`<button class="btn soft" type="button" data-status="todo">重新打开任务</button>`:`${t.status!=='doing'?`<button class="btn soft" type="button" data-status="doing" ${locked?'disabled':''}>开始任务</button>`:''}${t.status!=='review'?`<button class="btn" type="button" data-status="review" ${locked?'disabled':''}>提交复核</button>`:''}<button class="btn primary" type="button" data-status="done" ${locked?'disabled':''}>标记完成</button>${t.status!=='blocked'?`<button class="tiny-link" type="button" data-status="blocked">标记阻塞</button>`:''}`}</div></form>`;
    if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
  }
  function formValues(){const f=new FormData($('#task-form'));return Object.fromEntries(['title','role','goal','artifacts','note'].map(k=>[k,String(f.get(k)||'')]));}
  function saveTask(){MC.saveDelivery(state,selected,formValues());dirty=false;save();render();}
  function detailError(e){$('#detail-error').innerHTML=`<div class="inline-error">${escape(e.message||String(e))}</div>`;$('#detail-error').scrollIntoView({block:'center',behavior:'smooth'});}
  function showModal(title,body,footer=''){const m=$('#modal');m.innerHTML=`<div class="dialog-heading"><h2 id="modal-title">${title}</h2><button class="close-button" data-close="modal" aria-label="关闭弹窗">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-actions">${footer}</div>`:''}`;if(!m.open)m.showModal();}
  function confirmAction(title,msg,fn){pendingConfirm=fn;showModal(title,`<p>${escape(msg)}</p>`,`<button class="btn" data-close="modal">取消</button><button class="btn primary" data-action="confirm">确认继续</button>`);}
  function dataModal(){showModal('数据与备份',`<div class="info-card"><strong>进度保存在当前浏览器。</strong><br>刷新页面可继续使用。更换设备、浏览器或清除浏览记录前，请先导出 JSON 备份。本版不提供云端同步，也不会自动调用 AI。</div><div class="import-export-buttons"><button class="btn primary" data-action="export">${icon('download')}导出项目备份</button><button class="btn" data-action="import">导入 JSON 备份</button></div><p>当前项目：${escape(state.project)}<br>最近更新：${state.updatedAt?dateLabel(state.updatedAt):'尚未修改'}<br>记录范围：任务、状态、交付物、交接说明、自检勾选与重复核对。</p>${loadProblem?`<button class="btn" data-action="raw-export">导出原始存储</button>`:''}<div class="separator"></div><button class="tiny-link" data-action="reset">重置为空白任务模板</button>`);}
  function download(content,name){const blob=new Blob([content],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportState(){download(JSON.stringify(state,null,2),'MathorCup-项目备份-'+new Date().toISOString().slice(0,10)+'.json');toast('项目备份已导出');}
  function addModal(){showModal('新增项目任务',`<form id="add-form"><div id="add-error" role="alert"></div><label class="field"><span>任务名称</span><input name="title" required maxlength="100" placeholder="例如：补充异常样本分析"></label><label class="field"><span>所属阶段</span><select name="stage" id="new-stage">${stages.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label class="field"><span>本步目标</span><textarea name="goal" maxlength="30000" placeholder="定义清楚边界，避免重复安排已有工作"></textarea></label><label class="field"><span>预期交付物</span><input name="expected" required maxlength="500" placeholder="例如：01_分析/异常样本分析.md"></label><label class="field"><span>前置任务 <small style="display:inline">· 可多选</small></span><div id="dep-choices" class="dependency-choices"></div><small>只可选择同阶段或更早阶段的任务。</small></label><button class="btn primary" type="submit">创建任务</button></form>`);renderDepChoices();}
  function renderDepChoices(){const si=stages.findIndex(s=>s.id===$('#new-stage').value);$('#dep-choices').innerHTML=state.tasks.filter(t=>t.id!=='Q03'&&stages.findIndex(s=>s.id===t.stage)<=si).map(t=>`<label class="dep-choice"><input type="checkbox" name="deps" value="${t.id}"><span>${escape(t.id)} ${escape(t.title)}</span></label>`).join('');}
  async function copyPrompt(){if(dirty){try{saveTask();}catch(e){detailError(e);return;}}const text=MC.prompt(state,selected);showModal('AI 执行指令',`<p>复制后交给对应 AI，并附上实际输入文件。此处生成调度指令，不自动执行模型。</p><pre class="prompt-preview" id="prompt-text">${escape(text)}</pre>`,`<button class="btn primary" data-action="copy-prompt">${icon('copy')}复制指令</button>`);}
  document.addEventListener('click',async e=>{
    const b=e.target.closest('button,a.brand');if(!b)return;
    if(b.matches('a.brand')){e.preventDefault();changeView('workbench');return;}
    if(b.dataset.view){changeView(b.dataset.view);return;}
    if(b.dataset.stage){stageFilter=stageFilter===b.dataset.stage?'all':b.dataset.stage;quick='all';query='';changeView('workbench');return;}
    if(b.dataset.quick){quick=b.dataset.quick;render();return;}
    if(b.dataset.open){detail(b.dataset.open);return;}
    if(b.dataset.close){if(b.dataset.close==='detail'){if(!mayClose())return;$('#detail-dialog').close();selected=null;dirty=false;}else{$('#modal').close();pendingConfirm=null;}return;}
    if(b.dataset.status){try{saveTask();const status=b.dataset.status;const result=MC.transition(state,selected,status);if(result.requiresReset){const id=selected;confirmAction('重新核验后续任务',`这会把 ${result.affected.length} 项受影响的后续任务改为待开始，保留其交付物与说明供重新核验。确定重新打开？`,()=>{MC.transition(state,id,status,true);save();render();detail(id);toast('已重新打开，后续任务需复核');});}else{save();render();detail(selected);toast(status==='done'?'任务已完成，下游输入已就绪':'任务状态已更新');}}catch(err){detailError(err);}return;}
    if(b.hasAttribute('data-review-issue')){const issue=allIssues()[Number(b.dataset.reviewIssue)];if(!issue)return;state.duplicateReviews=state.duplicateReviews||{};const k=issueKey(issue);state.duplicateReviews[k]=!reviewed(issue);MC.record(state,'重复线索'+(state.duplicateReviews[k]?'已核对':'撤销核对')+'：'+issue.a+' / '+issue.b);save();render();return;}
    switch(b.dataset.action){
      case 'add':addModal();break;
      case 'data':dataModal();break;
      case 'export':exportState();break;
      case 'raw-export':{try{download(localStorage.getItem(KEY)||'null','MathorCup-原始存储.json');}catch{toast('无法读取浏览器存储');}break;}
      case 'import':$('#import-file').click();break;
      case 'reset':confirmAction('重置工作台','这将清除当前浏览器中的进度、交接说明和自检勾选，恢复 18 项空白模板。建议先导出备份。',()=>{state=MC.initial();save();stageFilter='all';quick='all';statusFilter='all';query='';view='workbench';render();toast('已重置为空白模板');});break;
      case 'confirm':{const fn=pendingConfirm;pendingConfirm=null;$('#modal').close();if(fn)fn();break;}
      case 'prompt':copyPrompt();break;
      case 'copy-prompt':{try{await navigator.clipboard.writeText($('#prompt-text').textContent);toast('执行指令已复制');}catch{const range=document.createRange();range.selectNodeContents($('#prompt-text'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('已选中全部指令，请按 Ctrl+C 或长按复制');}break;}
      case 'scan':scanTime=new Date().toISOString();render();toast('检查完成：'+unresolved().length+' 项待核对线索');break;
      case 'clear-filters':stageFilter='all';statusFilter='all';quick='all';query='';render();break;
      case 'activity':showModal('操作记录',state.log.length?`<div>${state.log.map(l=>`<div class="activity-item"><small>${escape(dateLabel(l.at))}</small>${escape(l.text)}</div>`).join('')}</div>`:'<p>还没有操作记录。开始第一个任务，留下推进的轨迹。</p>');break;
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='task-search'){query=e.target.value;renderTasks();}if(e.target.closest('#task-form'))dirty=true;});
  document.addEventListener('change',e=>{
    if(e.target.id==='stage-filter'){stageFilter=e.target.value;renderTasks();}
    if(e.target.id==='status-filter'){statusFilter=e.target.value;renderTasks();}
    if(e.target.id==='new-stage')renderDepChoices();
    if(e.target.hasAttribute('data-check')){const key=e.target.dataset.check;const final=state.tasks.find(t=>t.id==='Q03');if(final?.status==='done'&&!e.target.checked){toast('请先重新打开最终提交任务，再修改自检');e.target.checked=true;return;}state.checks[key]=e.target.checked;MC.record(state,(e.target.checked?'已确认自检：':'撤销自检：')+checks.find(c=>c[0]===key)[1]);save();render();}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='task-form'){e.preventDefault();try{saveTask();detail(selected);toast('交接记录已保存');}catch(err){detailError(err);}}if(e.target.id==='add-form'){e.preventDefault();try{const data=new FormData(e.target);MC.add(state,{title:String(data.get('title')),stage:String(data.get('stage')),goal:String(data.get('goal')),expected:String(data.get('expected')),deps:data.getAll('deps')});save();$('#modal').close();stageFilter='all';statusFilter='all';quick='all';query='';view='workbench';render();toast('任务已创建');}catch(err){$('#add-error').innerHTML=`<div class="inline-error">${escape(err.message)}</div>`;}}});
  $('#detail-dialog').addEventListener('cancel',e=>{if(!mayClose()){e.preventDefault();return;}selected=null;dirty=false;});
  $('#modal').addEventListener('cancel',()=>pendingConfirm=null);
  $('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>3*1024*1024)throw new Error('备份文件过大，最大支持 3 MB');const raw=JSON.parse(await file.text()),imported=MC.validate(raw);if(raw.duplicateReviews&&typeof raw.duplicateReviews==='object'){imported.duplicateReviews=Object.fromEntries(Object.entries(raw.duplicateReviews).filter(([k,v])=>typeof k==='string'&&k.length<2000&&v===true));}confirmAction('导入项目备份',`将用备份中的 ${imported.tasks.length} 项任务替换当前进度。请确认已保存当前备份。`,()=>{state=imported;MC.record(state,'从 JSON 备份恢复项目');save();view='workbench';stageFilter='all';statusFilter='all';quick='all';query='';render();toast('项目备份已恢复');});}catch(err){toast('导入失败：'+err.message);}});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  window.addEventListener('storage',e=>{if(e.key===KEY){toast('另一标签页已修改项目，请先导出当前进度，再刷新以读取最新记录');}});
  render();
})();
